use core.process as process

struct Command {
    kind: String
    name: String
    format: String
    dry_run: Bool
}

fn run() {
    args :: process.argv()
    raw_kind :: args.get(1) ?? panic("missing command")
    kind := ~raw_kind
    if kind == "ls" -> kind = "list"
    if kind == "rm" -> kind = "remove"
    if kind != "list" && kind != "inspect" && kind != "remove" -> panic("unknown command {raw_kind}")

    name := ""
    format := "text"
    dry_run := false
    have_name := false
    index := 2

    loop index < args.len() {
        arg :: args.get(index) ?? panic("missing argument")
        if arg == "--json" {
            format = "json"
            index = index + 1
            next
        }
        if arg == "--dry-run" {
            dry_run = true
            index = index + 1
            next
        }
        if arg == "--format" {
            index = index + 1
            format = args.get(index) ?? panic("missing format")
            if format != "text" && format != "json" -> panic("invalid format {format}")
            index = index + 1
            next
        }
        if arg.slice(0..1) == "-" -> panic("unknown option {arg}")
        if have_name -> panic("multiple names")
        name = arg
        have_name = true
        index = index + 1
    }
    if !have_name -> panic("missing name")

    command :: Command{kind: kind, name: name, format: format, dry_run: dry_run}
    dry_text :: if command.dry_run -> "true" else -> "false"
    if command.kind == "list" -> print("list name={command.name} format={command.format} dry_run={dry_text}")
    else {
        if command.kind == "inspect" -> print("inspect name={command.name} format={command.format} dry_run={dry_text}")
        else -> print("remove name={command.name} format={command.format} dry_run={dry_text}")
    }
}
